diff --git a/acceptance/acceptance_test.go b/acceptance/acceptance_test.go
new file mode 100644
index 0000000..3ed1fb4
--- /dev/null
+++ b/acceptance/acceptance_test.go
@@ -0,0 +1,353 @@
+// Package acceptance holds the spec's acceptance tests A1-A9, run against
+// the whole app: server.New over a temporary DataDir in an httptest server,
+// driven as a client would drive it. Each test builds its own server.
+package acceptance
+
+import (
+	"bytes"
+	"encoding/json"
+	"image/png"
+	"io"
+	"net/http"
+	"net/http/cookiejar"
+	"net/http/httptest"
+	"strings"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/server"
+)
+
+type user struct {
+	ID    int64  `json:"id"`
+	Email string `json:"email"`
+}
+
+type link struct {
+	Slug        string `json:"slug"`
+	URL         string `json:"url"`
+	TotalClicks int64  `json:"clicks"`
+	CreatedAt   string `json:"created_at"`
+}
+
+type dayStat struct {
+	Date  string `json:"date"`
+	Count int64  `json:"count"`
+}
+
+// client is an HTTP client with a cookie jar, so one per login session, and
+// no redirect following: the tests read the 302 of a short link themselves.
+type client struct {
+	t    *testing.T
+	srv  *httptest.Server
+	http *http.Client
+}
+
+func newClient(t *testing.T, srv *httptest.Server) *client {
+	t.Helper()
+	jar, err := cookiejar.New(nil)
+	if err != nil {
+		t.Fatalf("cookie jar: %v", err)
+	}
+	return &client{t: t, srv: srv, http: &http.Client{Jar: jar}}
+}
+
+// newServer starts the app over a database of its own.
+func newServer(t *testing.T) *httptest.Server {
+	t.Helper()
+	srv := httptest.NewServer(server.New(server.Config{DataDir: t.TempDir()}))
+	t.Cleanup(srv.Close)
+	return srv
+}
+
+// do sends a request to path and answers the response with its body already
+// read; the caller closes nothing. NoRedirect keeps a short link's 302 from
+// being followed away before the test can read it.
+func (c *client) do(method, path, body string) (*http.Response, []byte) {
+	c.t.Helper()
+	var r io.Reader
+	if body != "" {
+		r = strings.NewReader(body)
+	}
+	req, err := http.NewRequest(method, c.srv.URL+path, r)
+	if err != nil {
+		c.t.Fatalf("%s %s: %v", method, path, err)
+	}
+	if body != "" {
+		req.Header.Set("Content-Type", "application/json")
+	}
+	res, err := c.http.Do(req)
+	if err != nil {
+		c.t.Fatalf("%s %s: %v", method, path, err)
+	}
+	defer func() { _ = res.Body.Close() }()
+	b, err := io.ReadAll(res.Body)
+	if err != nil {
+		c.t.Fatalf("%s %s: read body: %v", method, path, err)
+	}
+	return res, b
+}
+
+func (c *client) mustJSON(method, path, body string, status int, v any) {
+	c.t.Helper()
+	res, b := c.do(method, path, body)
+	if res.StatusCode != status {
+		c.t.Fatalf("%s %s: %d, want %d (body %q)", method, path, res.StatusCode, status, b)
+	}
+	if v != nil {
+		if err := json.Unmarshal(b, v); err != nil {
+			c.t.Fatalf("%s %s: body %q is no JSON for %T: %v", method, path, b, v, err)
+		}
+	}
+}
+
+func (c *client) signup(email, password string) user {
+	c.t.Helper()
+	var u user
+	c.mustJSON(http.MethodPost, "/api/signup", `{"email":"`+email+`","password":"`+password+`"}`, http.StatusOK, &u)
+	if u.ID == 0 || u.Email != email {
+		c.t.Fatalf("signup answered %+v, want id and %s", u, email)
+	}
+	return u
+}
+
+func (c *client) login(email, password string) user {
+	c.t.Helper()
+	var u user
+	c.mustJSON(http.MethodPost, "/api/login", `{"email":"`+email+`","password":"`+password+`"}`, http.StatusOK, &u)
+	return u
+}
+
+func (c *client) me(status int) user {
+	c.t.Helper()
+	var u user
+	res, b := c.do(http.MethodGet, "/api/me", "")
+	if res.StatusCode != status {
+		c.t.Fatalf("GET /api/me: %d body %q, want %d", res.StatusCode, b, status)
+	}
+	if status == http.StatusOK {
+		if err := json.Unmarshal(b, &u); err != nil {
+			c.t.Fatalf("GET /api/me: body %q is no user JSON: %v", b, err)
+		}
+	}
+	return u
+}
+
+func (c *client) logout() {
+	c.t.Helper()
+	c.mustJSON(http.MethodPost, "/api/logout", "", http.StatusNoContent, nil)
+}
+
+func (c *client) createLink(url, slug string) link {
+	c.t.Helper()
+	var l link
+	c.mustJSON(http.MethodPost, "/api/links", `{"url":"`+url+`","slug":"`+slug+`"}`, http.StatusCreated, &l)
+	return l
+}
+
+func (c *client) listLinks() []link {
+	c.t.Helper()
+	var ls []link
+	c.mustJSON(http.MethodGet, "/api/links", "", http.StatusOK, &ls)
+	return ls
+}
+
+// getAnon fetches path without any session cookie and without following
+// redirects, on a client of its own.
+func getAnon(t *testing.T, srv *httptest.Server, path string) (*http.Response, []byte) {
+	t.Helper()
+	c := newClient(t, srv)
+	c.http.CheckRedirect = func(*http.Request, []*http.Request) error {
+		return http.ErrUseLastResponse
+	}
+	return c.do(http.MethodGet, path, "")
+}
+
+const pw = "correct horse battery"
+
+// A1: sign up, log in, GET /api/me returns user; log out, /api/me returns 401.
+func TestAuthFlow(t *testing.T) {
+	c := newClient(t, newServer(t))
+	signup := c.signup("alice@example.com", pw)
+	if got := c.me(http.StatusOK); got.ID != signup.ID || got.Email != "alice@example.com" {
+		t.Fatalf("GET /api/me after signup: %+v, want %+v", got, signup)
+	}
+
+	c.logout()
+	c.me(http.StatusUnauthorized)
+
+	login := c.login("alice@example.com", pw)
+	if login.ID != signup.ID {
+		t.Fatalf("login answered %+v, want the same user as signup %+v", login, signup)
+	}
+	if got := c.me(http.StatusOK); got.ID != signup.ID || got.Email != "alice@example.com" {
+		t.Fatalf("GET /api/me after login: %+v, want %+v", got, signup)
+	}
+
+	c.logout()
+	c.me(http.StatusUnauthorized)
+}
+
+// A2: create link, GET /<slug> returns 302 with Location; list shows 1 click.
+func TestRedirectAndCount(t *testing.T) {
+	srv := newServer(t)
+	c := newClient(t, srv)
+	c.signup("bob@example.com", pw)
+	created := c.createLink("https://example.com/a-page", "a2page")
+
+	res, _ := getAnon(t, srv, "/a2page")
+	if res.StatusCode != http.StatusFound {
+		t.Fatalf("GET /a2page: %d, want 302", res.StatusCode)
+	}
+	if got := res.Header.Get("Location"); got != "https://example.com/a-page" {
+		t.Fatalf("GET /a2page Location: %q, want the target", got)
+	}
+
+	links := c.listLinks()
+	if len(links) != 1 {
+		t.Fatalf("list answers %d links, want 1: %+v", len(links), links)
+	}
+	if links[0].Slug != "a2page" || links[0].TotalClicks != 1 {
+		t.Fatalf("list answers %+v, want slug a2page with 1 click", links[0])
+	}
+}
+
+// A3: duplicate custom slug returns 409; ftp:// URL returns 400.
+func TestSlugConflictAndValidation(t *testing.T) {
+	c := newClient(t, newServer(t))
+	c.signup("carol@example.com", pw)
+	c.createLink("https://example.com/one", "taken-slug")
+
+	res, b := c.do(http.MethodPost, "/api/links", `{"url":"https://example.com/two","slug":"taken-slug"}`)
+	if res.StatusCode != http.StatusConflict {
+		t.Fatalf("duplicate slug: %d body %q, want 409", res.StatusCode, b)
+	}
+
+	res, b = c.do(http.MethodPost, "/api/links", `{"url":"ftp://example.com/file","slug":"ftp-one"}`)
+	if res.StatusCode != http.StatusBadRequest {
+		t.Fatalf("ftp:// URL: %d body %q, want 400", res.StatusCode, b)
+	}
+}
+
+// A4: second user deleting first user's link returns 404; link still redirects.
+func TestCrossUserDelete(t *testing.T) {
+	srv := newServer(t)
+	owner := newClient(t, srv)
+	owner.signup("dave@example.com", pw)
+	owner.createLink("https://example.com/private", "owned-by-dave")
+
+	intruder := newClient(t, srv)
+	intruder.signup("erin@example.com", pw)
+	res, b := intruder.do(http.MethodDelete, "/api/links/owned-by-dave", "")
+	if res.StatusCode != http.StatusNotFound {
+		t.Fatalf("other user's DELETE: %d body %q, want 404", res.StatusCode, b)
+	}
+
+	res, _ = getAnon(t, srv, "/owned-by-dave")
+	if res.StatusCode != http.StatusFound || res.Header.Get("Location") != "https://example.com/private" {
+		t.Fatalf("GET /owned-by-dave after the failed delete: %d Location %q, want 302 to the target", res.StatusCode, res.Header.Get("Location"))
+	}
+}
+
+// A5: stats returns 30 entries, today's count is 2 after two redirects.
+func TestStatsThirtyDays(t *testing.T) {
+	srv := newServer(t)
+	c := newClient(t, srv)
+	c.signup("frank@example.com", pw)
+	c.createL
